		`    --gecos "" \`,
		`    --home "/nonexistent" \`,
		`    --shell "/usr/sbin/nologin" \`,
		"    --no-create-home \\",
		`    --uid "${UID}" \`,
		"    " + nonRootUser,
		"USER " + nonRootUser,
	}
	return strings.Join(lines, eol) + eol
}

