16	// rewrite. A test that asserted on the edits alone could pass while producing a
17	// file nobody would accept.
18	func apply(t *testing.T, src string, f scan.Finding) (string, string) {
19		t.Helper()
20		rule, ok := FixFor(f)
21		if !ok {
22			t.Fatalf("no rule for %q", f.ID)
23		}
24		edits, reason := rule.Fix([]byte(src), f)
25		if reason != "" {
26			return "", reason
27		}
28		out, err := patch.Rewrite([]byte(src), edits)
29		if err != nil {
30			t.Fatalf("Rewrite: %v", err)
31		}
32		return string(out), ""
33	}
34	
35	// Trivy spells the same rule two ways depending on which field it lands in.
36	// Matching one spelling only would leave the catalog silently inert.
37	func TestARuleIsFoundWhicheverWayItsIDIsSpelled(t *testing.T) {
38		for _, id := range []string{"AVD-DS-0002", "DS002", "ds002", "DS0002", "avd-ds-0002"} {
39			if _, ok := FixFor(misconf(id, "Dockerfile")); !ok {
