45	// The catalog answers for misconfigurations. A finding of another category
46	// reaching it is not an error — the tab is shared — it simply has no rule.
47	func TestOnlyAMisconfigurationGetsARule(t *testing.T) {
48		cve := scan.Finding{ID: "AVD-DS-0002", Source: scan.SourceTrivy}
49		if _, ok := FixFor(cve); ok {
50			t.Error("a vulnerability was offered a misconfiguration fix")
51		}
52	}
