55	// MCP server and a calling agent handle.
56	func TestARuleOutsideTheCatalogHasNoFix(t *testing.T) {
57		if _, ok := FixFor(misconf("AVD-DS-0026", "Dockerfile")); ok {
58			t.Error("an uncatalogued rule was offered a fix")
59		}
60	}
