62	// The account is created before it is used. A bare `USER 10001` switches to a
63	// uid with no passwd entry — no name, no home, no shell — and everything that
64	// asks the system who it is degrades at run time, far from this edit.
65	func TestTheAccountIsCreatedNotJustSwitchedTo(t *testing.T) {
66		src := "FROM debian:12\nENTRYPOINT [\"/app\"]\n"
67		got, reason := apply(t, src, misconf("AVD-DS-0002", "Dockerfile"))
68		if reason != "" {
69			t.Fatalf("declined: %s", reason)
70		}
71		for _, want := range []string{
72			"ARG UID=10001",
73			"RUN adduser \\",
74			"--disabled-password",
75			`--gecos ""`,
76			`--home "/nonexistent"`,
77			`--shell "/usr/sbin/nologin"`,
78			"--no-create-home",
79			`--uid "${UID}"`,
80			"USER appuser",
81		} {
